
const $=id=>document.getElementById(id);
const doCopy=async t=>{let ok=false;
  try{if(navigator.clipboard&&window.isSecureContext!==false){await navigator.clipboard.writeText(t);ok=true;}}catch(e){}
  if(!ok){try{const ta=document.createElement('textarea');ta.value=t;ta.setAttribute('readonly','');ta.style.cssText='position:fixed;left:-9999px;top:0;opacity:0';document.body.appendChild(ta);ta.select();ta.setSelectionRange(0,t.length);ok=document.execCommand('copy');ta.remove();}catch(e){}}
  const bt=$('copy').firstElementChild;let box=$('copytxt');
  if(ok){if(box)box.remove();bt.textContent='Скопировано';}
  else{bt.textContent='Скопируйте вручную (Ctrl+C)';if(!box){box=document.createElement('textarea');box.id='copytxt';box.readOnly=true;box.rows=8;box.style.cssText='width:100%;margin-top:12px;border:1.5px solid #C7D0DC;border-radius:12px;padding:12px;font:500 13px/1.45 Manrope,sans-serif;color:#2D3748;resize:vertical';$('copy').after(box);}box.value=t;box.focus();box.select();}
  setTimeout(()=>{const b=$('copy');b&&(b.firstElementChild.textContent='Скопировать смету');},2200);};
const S={type:'a1',W:6,L:6,H:2.1,cs:3,ts:2,rise:18,col:'80',tr:'40x40',roof:'poly',frame:'#1d1f22',rc:'#c98a3a',paint:true,mount:true,mode:'std',st:'a1',mt:'mflat',ov:.5,fh:.45,fz:'none',fc:'#383e42',hb:'none',hd:2.5,cl:'none',led:false,ledf:false,gutter:false,walls:false,charger:false,slab:false};

/* ---------- данные (цены условные — замените на свои) ---------- */
const kgm=(a,b,t=.003)=>(2*(a+b)/1000-4*t)*t*7850;
const COL={60:{kg:kgm(60,60)},80:{kg:kgm(80,80)},100:{kg:kgm(100,100,.004)},120:{kg:kgm(120,120,.005)},140:{kg:kgm(140,140,.005)},160:{kg:kgm(160,160,.006)},180:{kg:kgm(180,180,.006)},200:{kg:kgm(200,200,.006)}};
Object.values(COL).forEach(c=>c.p=c.kg*60);
const TRS={};['40x40','60x40','50x50','60x60','80x40'].forEach(k=>{const [h,w]=k.split('x').map(Number);TRS[k]={h:h/1000,w:w/1000,kg:kgm(h,w)};TRS[k].p=TRS[k].kg*65;});
const PURLIN={p:120,kg:1.7};
const ROOF={poly:{n:'Сотовый поликарбонат',p:780},mono:{n:'Монолитный поликарбонат',p:2200},prof:{n:'Профнастил',p:650},tile:{n:'Металлочерепица',p:720},soft:{n:'Гибкая черепица',p:1450}};
const RAL=[['#1d1f22','RAL 9005 Чёрный'],['#383e42','RAL 7016 Антрацит'],['#4a3228','RAL 8017 Шоколад'],['#2f4538','RAL 6005 Зелёный мох'],['#1f4e8c','RAL 5005 Синий'],['#7b2820','RAL 3011 Красно-коричневый'],['#8e402a','RAL 8004 Терракот'],['#ecedeb','RAL 9003 Белый'],['#a1a5a7','RAL 9006 Серебристый']];
const RC={
 poly:[['#e8f4f8','Прозрачный'],['#c98a3a','Бронза'],['#3f78c4','Синий'],['#4fa37f','Зелёный'],['#f1f1ee','Молочный']],
 mono:[['#e6f3f7','Прозрачный'],['#c98a3a','Бронза'],['#6f7a82','Дымчатый'],['#3f78c4','Синий']],
 soft:[['#a63a2e','Красный'],['#5b3a29','Коричневый'],['#5d6469','Графит'],['#2f6b4a','Зелёный'],['#2d4a73','Синий']],
 op:RAL.filter(r=>['3011','8004','8017','7016','6005','5005','9003','9006'].some(c=>r[1].includes(c)))};
const rcList=()=>RC[S.roof==='poly'||S.roof==='mono'||S.roof==='soft'?S.roof:'op'];
// Профили ферм: p(t,R,d) -> [верх, низ], t=0..1 поперёк ширины, R — подъём, d — высота фермы
const F=W=>Math.max(.5,.55+.15*(W-3));            // высоты каталога (пролёт 6 м) → масштаб по пролёту
const sA=t=>Math.abs(2*t-1),pa=t=>1-(2*t-1)*(2*t-1),qc=t=>1-(1-t)*(1-t);
const camber=(t,W,c)=>{const s=sA(t),s0=1-1.646/W;return s<s0?c*(1-(s/s0)*(s/s0)):0;};
const bld=sp=>W=>{const f=F(W),n=sp.nn(W),P=[],Q=[];
  for(let i=0;i<=n;i++){const t=i/n;P.push([-W/2+W*t,sp.top(t,W)*f]);Q.push([-W/2+W*t,sp.bot(t,W)*f]);}
  const web=[],ln=(a,b)=>web.push([a,b]),h=n/2,dp=i=>P[i][1]-Q[i][1],w=sp.web;
  if(typeof w==='function')w(P,Q,ln,n);
  else{
    if(w==='pratt')for(let i=0;i<n;i++)i<h?ln(P[i],Q[i+1]):ln(P[i+1],Q[i]);
    if(w==='warren'||w==='wv')for(let i=0;i<n;i++)i%2?ln(Q[i],P[i+1]):ln(P[i],Q[i+1]);
    if(w==='pratt'||w==='wv'||w==='ladder')for(let i=1;i<n;i++)if(dp(i)>.03)ln(P[i],Q[i]);
    if(sp.vc&&w==='warren')ln(P[h],Q[h]);
  }
  [0,n].forEach(i=>{if(dp(i)>.08)ln(P[i],Q[i]);});   // торцевая стойка, если у фермы есть высота на опоре
  return{top:P,bot:Q,web};};
const nG=W=>2*Math.round(W*1.2),nA=W=>2*Math.round(W*1.5),nM=W=>2*Math.round(W/1.5);
const TY={
 d1:{n:'Двускатная «Д-1»',c:'Д-1',make:bld({nn:nG,top:t=>.06+.94*(1-sA(t)),bot:()=>0,web:'pratt'})},
 d2:{n:'Двускатная «Д-2»',c:'Д-2',make:bld({nn:nG,top:t=>.06+.94*(1-sA(t)),bot:(t,W)=>camber(t,W,.34),web:'pratt'})},
 d3:{n:'Двускатная «Д-3»',c:'Д-3',make:bld({nn:nG,top:t=>.29+.71*(1-sA(t)),bot:(t,W)=>{const s=sA(t),s0=1-1.646/W;return s<s0?.71*(s0-s):0;},web:'warren',vc:1})},
 d4:{n:'Двускатная «Д-4»',c:'Д-4',make:bld({nn:nG,top:t=>.3+.7*(1-sA(t)),bot:t=>.405*(1-sA(t)),web:'warren',vc:1})},
 d5:{n:'Двускатная «Д-5»',c:'Д-5',make:bld({nn:()=>12,top:t=>.9*(1-sA(t)),bot:()=>0,web:(P,Q,ln)=>{ln(P[6],Q[6]);ln(Q[2],P[4]);ln(P[4],Q[6]);ln(Q[10],P[8]);ln(P[8],Q[6]);}})},
 d6:{n:'Двускатная «Д-6»',c:'Д-6',make:bld({nn:()=>12,top:t=>.9*(1-sA(t)),bot:()=>0,web:(P,Q,ln)=>{ln(Q[3],P[6]);ln(P[6],Q[9]);}})},
 a1:{n:'Арочная «А-1»',c:'А-1',make:bld({nn:nA,top:t=>.05+.75*pa(t),bot:()=>0,web:'pratt'})},
 a2:{n:'Арочная «А-2»',c:'А-2',make:bld({nn:nA,top:t=>.3+.7*pa(t),bot:t=>.7*pa(t),web:'warren'})},
 a3:{n:'Арочная «А-3»',c:'А-3',make:bld({nn:nA,top:t=>.9*pa(t),bot:t=>.3*pa(t),web:'warren',vc:1})},
 a4:{n:'Арочная «А-4»',c:'А-4',make:bld({nn:nA,top:t=>.35+.65*pa(t),bot:t=>.45*pa(t),web:'ladder'})},
 a5:{n:'Арочная «А-5»',c:'А-5',make:bld({nn:nA,top:t=>.28+.62*pa(t),bot:t=>.5*pa(t),web:'ladder'})},
 a6:{n:'Арочная «А-6»',c:'А-6',make:bld({nn:nA,top:t=>.12+.68*pa(t),bot:t=>.65*pa(t),web:'none'})},
 o1:{n:'Односкатная «О-1»',c:'О-1',make:bld({nn:W=>Math.max(4,Math.round(W/.75)),top:t=>.14+.6*t,bot:()=>0,web:'wv'})},
 o2:{n:'Односкатная «О-2»',c:'О-2',make:bld({nn:nM,top:t=>.5*t+.32,bot:t=>.5*t,web:'warren'})},
 o3:{n:'Односкатная «О-3»',c:'О-3',make:bld({nn:()=>8,top:t=>.45*t+.1,bot:t=>.45*t,web:'none'})},
 p1:{n:'Полуарочная «П-1»',c:'П-1',make:bld({nn:nM,top:t=>.5*qc(t)+.1+.42*t,bot:t=>.5*qc(t),web:'warren'})},
 p2:{n:'Полуарочная «П-2»',c:'П-2',make:bld({nn:nA,top:t=>qc(t)+.04+.46*t,bot:t=>qc(t),web:'ladder'})},
 p3:{n:'Полуарочная «П-3»',c:'П-3',make:bld({nn:()=>16,top:t=>qc(t)+.1,bot:t=>qc(t),web:'none'})},
 mflat:{n:'Плоская кровля',mod:1,s0:3},
 mmono:{n:'Односкатная',mod:1,s0:10},
 mcant:{n:'Консольная (столбы с одной стороны)',mod:1,s0:6}
};
