  if(S.mount)rows.push(['Монтаж и доставка',fmt(mount)+' ₽']);
  const total=Math.round((sub+mount)/100)*100;
  const spec=`<h2>Спецификация металла</h2><table class="sp">${sp.map(r=>`<tr><td>${r[0]}<small>${r[1]}</small></td><td>${r[2]} × ${fmt(r[3],1)} м</td><td>${fmt(r[2]*r[3],1)} пог.м</td></tr>`).join('')}</table>`;
  showEst(`Современный навес «${T.n}» ${W}×${L} м, ${ROOF[S.roof].n}`,rows,total,spec);
  $('tagt').textContent=`${fmt(Lr,1)} × ${fmt(Wr,1)} м · ${fmt(Lr*Wr,1)} м²`;
  tgt.set(xc,(Math.max(base(za),base(zE))+PK)/2,zm);
