function update(){sync();build();}

/* ---------- камера ---------- */
const tgt=V(0,1.5,0),D={th:.75,ph:1.1,r:15};let auto=false;
function place(){cam.position.set(tgt.x+D.r*Math.sin(D.ph)*Math.sin(D.th),tgt.y+D.r*Math.cos(D.ph),tgt.z+D.r*Math.sin(D.ph)*Math.cos(D.th));cam.lookAt(tgt);}
const fit=()=>cam.aspect<1.15?Math.min(2.2,1.2/cam.aspect):1;                      // на узком экране отодвигаем камеру, чтобы модель помещалась
function refit(){D.r=(Math.max(S.W,S.L)*1.5+5)*fit();D.hr=D.r;}
function home(){D.th=.75;D.ph=1.1;refit();}
let drag=null;
cv.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};cv.setPointerCapture(e.pointerId);});
cv.addEventListener('pointermove',e=>{if(!drag)return;D.th-=(e.clientX-drag.x)*.007;D.ph=Math.min(1.52,Math.max(.15,D.ph-(e.clientY-drag.y)*.007));drag={x:e.clientX,y:e.clientY};});
cv.addEventListener('pointerup',()=>drag=null);cv.addEventListener('pointercancel',()=>drag=null);
cv.addEventListener('wheel',e=>{e.preventDefault();D.r=Math.min(45,Math.max(4,D.r*(1+Math.sign(e.deltaY)*.08)));},{passive:false});
$('auto').onclick=()=>{auto=!auto;$('auto').setAttribute('aria-pressed',auto);};
$('reset').onclick=home;
function size(){const v=$('view');R.setSize(v.clientWidth,v.clientHeight,false);cam.aspect=v.clientWidth/Math.max(1,v.clientHeight);cam.updateProjectionMatrix();if(D.hr&&Math.abs(D.r-D.hr)<1e-6)refit();}
new ResizeObserver(size).observe($('view'));
let modelVisible=true;
if('IntersectionObserver' in window){new IntersectionObserver(entries=>{modelVisible=!!entries[0]?.isIntersecting;},{rootMargin:'180px'}).observe($('view'));}
(function loop(){if(modelVisible&&!document.hidden){if(auto&&!drag)D.th+=.004;place();R.render(scene,cam);}requestAnimationFrame(loop);})();
update();size();home();


